tinymce.PluginManager.add("myplugin", function (editor, url) {
    // thêm button lên toolbar
    editor.ui.registry.addButton("mybutton", {
        text: "My Button",
        onAction: function () {
            editor.insertContent("<p>Xin chào từ plugin 🚀</p>");
        },
    });

    // thêm menu item
    editor.ui.registry.addMenuItem("mymenu", {
        text: "Chèn nội dung",
        onAction: function () {
            editor.insertContent("<strong>Nội dung từ menu</strong>");
        },
    });
});
